const raw = $input.first().json || {};
const headers = raw.headers || {};
const token = String(headers['x-internal-token'] || headers['X-Internal-Token'] || '').trim();
const want = String($env.INTERNAL_API_TOKEN || '').trim();
if (!want || token !== want) {
  throw new Error('forbidden');
}
const body = (raw.body && typeof raw.body === 'object') ? raw.body : raw;
return [{ json: body }];

function digits(s) { return String(s || '').replace(/\D/g, ''); }
function clip(s, n) { return String(s || '').trim().slice(0, n); }
const j = $input.first().json || {};
const channel = String(j.channel || '').toLowerCase();
const slug = clip(j.slug || j.name || 'campaign', 80) || 'campaign';
const statusIn = String(j.campaign_status || 'PAUSED').toUpperCase();
const googleStatus = statusIn === 'ENABLED' ? 'ENABLED' : 'PAUSED';
const metaStatus = googleStatus === 'ENABLED' ? 'ACTIVE' : 'PAUSED';
const capN = Number(j.daily_cap);
const cap = Number.isFinite(capN) && capN > 0 ? capN : 0;
const finalUrl = String(j.final_url || '').trim();
const headlines = (Array.isArray(j.headlines) ? j.headlines : []).map((h) => clip(h, 30)).filter(Boolean).slice(0, 15);
const descriptions = (Array.isArray(j.descriptions) ? j.descriptions : []).map((d) => clip(d, 90)).filter(Boolean).slice(0, 4);
const keywords = (Array.isArray(j.keywords) ? j.keywords : []).map((k) => clip(k, 80)).filter(Boolean).slice(0, 20);
const cells = (Array.isArray(j.cells) ? j.cells : []).map((c) => ({ geo: clip(c && c.geo, 80), theme: clip(c && c.theme, 80), why: clip(c && c.why, 120) })).filter((c) => c.geo || c.theme).slice(0, 5);
if (!finalUrl || headlines.length < 3 || descriptions.length < 2 || !keywords.length) {
  return [{ json: { skip: true, status: 'error', audit_text: 'Pack needs a final URL, three headlines, two descriptions, and a keyword.' } }];
}
const experiments = (cells.length ? cells : [{ geo: 'Nigeria', theme: 'search' }]).map((c) => ({
  geo: c.geo || 'Nigeria',
  theme: c.theme || 'search',
  name: clip([slug, c.geo || 'Nigeria', c.theme || 'search'].filter(Boolean).join(' · '), 100),
  url: clip(c.url || finalUrl, 500)
}));
const geoNames = [...new Set(experiments.map((e) => e.geo).filter(Boolean))];
if (!geoNames.includes('Nigeria')) geoNames.push('Nigeria');
const geoQuery = "SELECT geo_target_constant.resource_name, geo_target_constant.name, geo_target_constant.canonical_name, geo_target_constant.country_code, geo_target_constant.target_type FROM geo_target_constant WHERE geo_target_constant.status = 'ENABLED' AND geo_target_constant.name IN (" + geoNames.map((g) => "'" + String(g).replace(/'/g, '') + "'").join(', ') + ")";
const base = { skip: false, slug, cap, google_status: googleStatus, meta_status: metaStatus, final_url: finalUrl, headlines, descriptions, keywords, experiments, geo_query: geoQuery };
if (channel === 'google') {
  const cid = digits(j.google_customer_id);
  const login = digits(j.google_login_customer_id) || cid;
  const token = String($env.GOOGLE_ADS_DEVELOPER_TOKEN || '').trim();
  if (!cid) return [{ json: { skip: true, status: 'error', audit_text: 'Paste the Google Ads customer id on Defaults → Ads.' } }];
  if (!token) return [{ json: { skip: true, status: 'error', audit_text: 'GOOGLE_ADS_DEVELOPER_TOKEN is missing on n8n.' } }];
  return [{ json: { ...base, channel: 'google', customer_id: cid, login_customer_id: login, funds_query: "SELECT account_budget.approved_spending_limit_micros, account_budget.approved_spending_limit_type, account_budget.amount_served_micros, account_budget.total_adjustments_micros, account_budget.status FROM account_budget WHERE account_budget.status = 'APPROVED'" } }];
}
if (channel === 'meta') {
  let act = String(j.meta_ad_account_id || '').trim();
  if (act.toLowerCase().startsWith('act_')) act = act.slice(4);
  act = digits(act);
  const pageId = digits(j.meta_page_id);
  if (!act || !pageId) return [{ json: { skip: true, status: 'error', audit_text: 'Paste the Meta ad account id and Page id on Defaults → Ads.' } }];
  return [{ json: { ...base, channel: 'meta', act_id: act, page_id: pageId } }];
}
return [{ json: { skip: true, status: 'error', audit_text: 'Pick Google Search or Meta.' } }];

function flattenSearch(res) {
  if (Array.isArray(res)) return res.flatMap((chunk) => chunk.results || []);
  if (res && Array.isArray(res.results)) return res.results;
  return [];
}
function num(v) { const n = Number(v); return Number.isFinite(n) ? n : 0; }
function conservativeDaily(remaining, cap, minDaily, infinite) {
  if (infinite && remaining <= 0) {
    if (!(cap > 0)) return { ok: false, audit: 'Google Ads did not report remaining funds (open-ended or empty). Set a ceiling on Defaults → Ads so Place does not run unbounded.' };
    if (cap < minDaily) return { ok: false, audit: 'Defaults ceiling is below the Google minimum daily (1 in account currency).' };
    return { ok: true, daily: minDaily, how: 'open-ended account, platform minimum probe' };
  }
  if (remaining < minDaily) return { ok: false, audit: 'Google Ads remaining is too low to schedule (need at least 1 in account currency). Add funds, then Place again.' };
  if (cap > 0 && cap < minDaily) return { ok: false, audit: 'Defaults ceiling is below the Google minimum daily (1 in account currency).' };
  let daily = minDaily;
  const reserve = Math.floor(remaining / 90);
  if (reserve >= minDaily) daily = Math.min(daily, reserve);
  if (cap > 0) daily = Math.min(daily, cap);
  return { ok: true, daily, how: 'platform minimum probe; never above remaining/90 or Defaults ceiling' };
}
const p = $('Prepare pack').item.json;
const fundsRes = $('GET Google funds').first().json || {};
if (fundsRes.error) {
  const msg = (fundsRes.error && (fundsRes.error.message || fundsRes.error.status)) || JSON.stringify(fundsRes);
  return [{ json: { skip: true, status: 'error', audit_text: 'Google Ads funds: ' + String(msg).slice(0, 400) } }];
}
const fundRows = flattenSearch(fundsRes);
let remaining = 0;
let infinite = fundRows.length === 0;
for (const row of fundRows) {
  const b = row.accountBudget || row.account_budget || {};
  const type = String(b.approvedSpendingLimitType || b.approved_spending_limit_type || '');
  if (type === 'INFINITE') { infinite = true; continue; }
  const limit = num(b.approvedSpendingLimitMicros || b.approved_spending_limit_micros);
  const served = num(b.amountServedMicros || b.amount_served_micros);
  const adj = num(b.totalAdjustmentsMicros || b.total_adjustments_micros);
  const left = limit - served + adj;
  if (left > remaining) remaining = left;
}
const capMicros = p.cap > 0 ? Math.round(p.cap * 1e6) : 0;
const minDaily = 1000000;
const bud = conservativeDaily(remaining, capMicros, minDaily, infinite);
if (!bud.ok) return [{ json: { skip: true, status: 'error', audit_text: bud.audit } }];
const daily = bud.daily;
const how = bud.how;
let geoRows = [];
try { geoRows = flattenSearch($('GET Google geos').first().json || {}); } catch (e) {}
function scoreGeo(row, want) {
  const g = row.geoTargetConstant || row.geo_target_constant || {};
  const name = String(g.name || '').toLowerCase();
  const canon = String(g.canonicalName || g.canonical_name || '').toLowerCase();
  const cc = String(g.countryCode || g.country_code || '').toUpperCase();
  const type = String(g.targetType || g.target_type || '');
  const w = String(want || '').toLowerCase();
  if (!w || (name !== w && canon.indexOf(w) < 0)) return -1;
  let s = 1;
  if (name === w) s += 5;
  if (cc === 'NG') s += 4;
  if (type === 'City') s += 3;
  if (type === 'Region' || type === 'Province' || type === 'State') s += 2;
  if (type === 'Country') s += 1;
  return s;
}
function geoFor(want) {
  let best = null, bestS = 0;
  for (const row of geoRows) {
    const s = scoreGeo(row, want);
    if (s > bestS) { bestS = s; best = row.geoTargetConstant || row.geo_target_constant; }
  }
  return (best && (best.resourceName || best.resource_name)) || '';
}
function keysFor(theme, geo, all) {
  const tokens = (String(theme || '') + ' ' + String(geo || '')).toLowerCase().split(/\s+/).filter((x) => x.length >= 3);
  const hit = all.filter((k) => tokens.some((tok) => k.toLowerCase().includes(tok)));
  return hit.length ? hit : all;
}
const cust = 'customers/' + p.customer_id;
const operations = [
  { campaignBudgetOperation: { create: { resourceName: cust + '/campaignBudgets/-1', name: p.slug + ' daily', amountMicros: String(daily), deliveryMethod: 'STANDARD', explicitlyShared: false } } },
  { campaignOperation: { create: { resourceName: cust + '/campaigns/-2', name: p.slug, status: p.google_status, advertisingChannelType: 'SEARCH', campaignBudget: cust + '/campaignBudgets/-1', containsEuPoliticalAdvertising: 'DOES_NOT_CONTAIN_EU_POLITICAL_ADVERTISING', networkSettings: { targetGoogleSearch: true, targetSearchNetwork: false, targetContentNetwork: false, targetPartnerSearchNetwork: false }, maximizeClicks: { cpcBidCeilingMicros: String(Math.min(daily, minDaily)) } } } }
];
const experiments = p.experiments || [];
experiments.forEach((ex, i) => {
  const ag = cust + '/adGroups/' + (-(10 + i));
  operations.push({ adGroupOperation: { create: { resourceName: ag, name: ex.name, campaign: cust + '/campaigns/-2', status: 'ENABLED', type: 'SEARCH_STANDARD' } } });
  operations.push({ adGroupAdOperation: { create: { adGroup: ag, status: p.google_status, ad: { responsiveSearchAd: { headlines: p.headlines.map((text) => ({ text })), descriptions: p.descriptions.map((text) => ({ text })) }, finalUrls: [ex.url || p.final_url] } } } });
  const loc = geoFor(ex.geo);
  if (loc) operations.push({ adGroupCriterionOperation: { create: { adGroup: ag, location: { geoTargetConstant: loc } } } });
  for (const text of keysFor(ex.theme, ex.geo, p.keywords)) {
    operations.push({ adGroupCriterionOperation: { create: { adGroup: ag, status: 'ENABLED', keyword: { text, matchType: 'EXACT' } } } });
  }
});
const remainingUnits = remaining / 1e6;
const dailyUnits = daily / 1e6;
return [{ json: {
  skip: false,
  customer_id: p.customer_id,
  login_customer_id: p.login_customer_id,
  google_body: { mutateOperations: operations },
  slug: p.slug,
  google_status: p.google_status,
  experiment_count: experiments.length,
  remaining_units: remainingUnits,
  daily_units: dailyUnits,
  budget_how: how,
  audit_preview: 'Conservative Place. Google Ads remaining ~' + remainingUnits.toFixed(2) + '. Daily ' + dailyUnits.toFixed(2) + ' (' + how + '). ' + experiments.length + ' cell experiments, all Lagos hours for a week, exact match, Google Search only. Status ' + p.google_status + '.'
} }];

const p = $('Build Google').item.json;
const res = $input.first().json || {};
if (res.error || !Array.isArray(res.mutateOperationResponses)) {
  const msg = (res.error && (res.error.message || res.error.status)) || res.message || JSON.stringify(res);
  return [{ json: { skip: true, status: 'error', audit_text: 'Google Ads: ' + String(msg).slice(0, 400) } }];
}
const ops = res.mutateOperationResponses || [];
const camp = (ops[1] && ops[1].campaignResult && ops[1].campaignResult.resourceName) || '';
const audit = (p.audit_preview || 'Placed Google Search.') + ' Campaign ' + (camp || p.slug) + '.';
return [{ json: { status: 'ok', channel: 'google', id: camp, campaign_id: camp, resource_name: camp, audit_text: audit } }];

function num(v) { const n = Number(v); return Number.isFinite(n) ? n : 0; }
function form(obj) {
  return Object.keys(obj).map((k) => {
    const v = String(obj[k]);
    if (v.indexOf('{result=') >= 0) return encodeURIComponent(k) + '=' + v;
    return encodeURIComponent(k) + '=' + encodeURIComponent(v);
  }).join('&');
}
function conservativeDaily(remaining, cap, minDaily, infinite) {
  if (infinite && remaining <= 0) {
    if (!(cap > 0)) return { ok: false, audit: 'Meta did not report a remaining amount. Set a ceiling on Defaults → Ads so Place does not run unbounded.' };
    if (cap < minDaily) return { ok: false, audit: 'Defaults ceiling is below Meta’s minimum daily budget.' };
    return { ok: true, daily: minDaily, how: 'open-ended account, platform minimum probe' };
  }
  if (remaining < minDaily) return { ok: false, audit: 'Meta remaining is too low to schedule. Add funds, then Place again.' };
  if (cap > 0 && cap < minDaily) return { ok: false, audit: 'Defaults ceiling is below Meta’s minimum daily budget.' };
  let daily = minDaily;
  const reserve = Math.floor(remaining / 90);
  if (reserve >= minDaily) daily = Math.min(daily, reserve);
  if (cap > 0) daily = Math.min(daily, cap);
  return { ok: true, daily, how: 'platform minimum probe; never above remaining/90 or Defaults ceiling' };
}
const p = $('Prepare pack').item.json;
const acc = $('GET Meta account').first().json || {};
if (acc.error) {
  const err = acc.error || acc;
  return [{ json: { skip: true, status: 'error', audit_text: 'Meta account: ' + String(err.error_user_msg || err.message || JSON.stringify(acc)).slice(0, 400) } }];
}
const balance = num(acc.balance);
const spent = num(acc.amount_spent);
const spendCap = num(acc.spend_cap);
const minDaily = Math.max(num(acc.min_daily_budget), 100);
let remaining = 0;
let infinite = false;
if (spendCap > 0) remaining = Math.max(0, spendCap - spent);
else if (balance > 0) remaining = balance;
else infinite = true;
const capCents = p.cap > 0 ? Math.round(p.cap * 100) : 0;
const bud = conservativeDaily(remaining, capCents, minDaily, infinite);
if (!bud.ok) return [{ json: { skip: true, status: 'error', audit_text: bud.audit } }];
const daily = bud.daily;
const how = bud.how;
const experiments = p.experiments || [];
const batch = [];
batch.push({ method: 'POST', name: 'camp', relative_url: 'act_' + p.act_id + '/campaigns', body: form({ name: p.slug, objective: 'OUTCOME_TRAFFIC', status: p.meta_status, special_ad_categories: '[]', daily_budget: String(daily), bid_strategy: 'LOWEST_COST_WITHOUT_CAP' }) });
experiments.forEach((ex, i) => {
  const setName = 'set' + i;
  const crName = 'cr' + i;
  batch.push({ method: 'POST', name: crName, relative_url: 'act_' + p.act_id + '/adcreatives', body: form({ name: ex.name + ' creative', object_story_spec: JSON.stringify({ page_id: p.page_id, link_data: { link: ex.url || p.final_url, message: p.descriptions[0], name: p.headlines[0], call_to_action: { type: 'LEARN_MORE' } } }) }) });
  batch.push({ method: 'POST', name: setName, relative_url: 'act_' + p.act_id + '/adsets', body: form({ name: ex.name, campaign_id: '{result=camp:$.id}', billing_event: 'IMPRESSIONS', optimization_goal: 'LINK_CLICKS', status: p.meta_status, targeting: JSON.stringify({ geo_locations: { countries: ['NG'] } }), promoted_object: JSON.stringify({ page_id: p.page_id }) }) });
  batch.push({ method: 'POST', name: 'ad' + i, relative_url: 'act_' + p.act_id + '/ads', body: form({ name: ex.name + ' ad', adset_id: '{result=' + setName + ':$.id}', creative: JSON.stringify({ creative_id: '{result=' + crName + ':$.id}' }), status: p.meta_status }) });
});
const remainingUnits = remaining / 100;
const dailyUnits = daily / 100;
return [{ json: {
  skip: false,
  batch,
  slug: p.slug,
  meta_status: p.meta_status,
  experiment_count: experiments.length,
  remaining_units: remainingUnits,
  daily_units: dailyUnits,
  budget_how: how
} }];

function parseBody(item) {
  if (!item) return {};
  const body = item.body;
  if (typeof body === 'string') {
    try { return JSON.parse(body); } catch (e) { return { message: body }; }
  }
  return body || item;
}
const p = $('Build Meta').item.json;
const raw = $input.first().json;
const list = Array.isArray(raw) ? raw : (raw && Array.isArray(raw.data) ? raw.data : [raw]);
const first = list[0] || {};
const camp = parseBody(first);
if ((first.code && first.code >= 400) || camp.error || !camp.id) {
  const msg = (camp.error && (camp.error.message || camp.error.error_user_msg)) || camp.message || JSON.stringify(camp);
  return [{ json: { skip: true, status: 'error', audit_text: 'Meta: ' + String(msg).slice(0, 400) } }];
}
const audit = 'Placed Meta campaign ' + camp.id + ' (' + p.meta_status + '). Account remaining ~' + Number(p.remaining_units).toFixed(2) + '. Daily ' + Number(p.daily_units).toFixed(2) + ' (' + p.budget_how + '). ' + p.experiment_count + ' cell experiments, all Lagos hours for a week, one campaign budget so Meta can shift to what works.';
